<?php
namespace App\Http\Controllers;
use App\Models\{Equipment,School,SparePart,Ticket,TicketStatusHistory,User};
use App\Notifications\TicketEventNotification;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;

class TicketController extends Controller
{
    public function index(Request $request){ $q=Ticket::with(['school','equipment','requester','technician'])->latest(); $this->scope($q,$request); if($request->filled('status'))$q->where('estado',Ticket::databaseValue('status',$request->status)); if($request->filled('search'))$q->where(fn($x)=>$x->where('codigo','like','%'.$request->search.'%')->orWhere('asunto','like','%'.$request->search.'%')); return view('tickets.index',['tickets'=>$q->paginate(12)->withQueryString()]); }
    public function create(Request $request){ return view('tickets.create',['schools'=>$request->user()->isDirector()?School::whereKey($request->user()->school_id)->get():School::where('activo',true)->orderBy('nombre')->get(),'equipment'=>Equipment::orderBy('codigo_patrimonial')->get()]); }
    public function store(Request $request){ $data=$request->validate(['school_id'=>'required|exists:unidades_educativas,id','equipment_id'=>'nullable|exists:equipos,id','category'=>'required|in:hardware,software,connectivity','priority'=>'required|in:low,medium,high,critical','subject'=>'required|string|max:255','description'=>'required|string|max:5000']); if($request->user()->isDirector())$data['school_id']=$request->user()->school_id; $data['requester_id']=$request->user()->id; $data['status']='pending'; $data['code']='SOL-'.now()->format('Ym').'-'.strtoupper(Str::random(6)); $ticket=DB::transaction(function()use($data,$request){$t=Ticket::create($data); TicketStatusHistory::create(['ticket_id'=>$t->id,'changed_by'=>$request->user()->id,'to_status'=>'pending','comment'=>'Solicitud registrada']); if($t->equipment)$t->equipment->update(['status'=>'under_repair']); return $t;}); User::whereIn('role',['admin','technician'])->where('active',true)->get()->each->notify(new TicketEventNotification($ticket,'new')); return redirect()->route('tickets.show',$ticket)->with('success','Solicitud registrada correctamente.'); }
    public function show(Request $request, Ticket $ticket){ $this->authorizeView($request,$ticket); $ticket->load(['school','equipment','requester','technician','histories.user','interventions.technician','interventions.spareParts']); return view('tickets.show',['ticket'=>$ticket,'technicians'=>User::where('role','technician')->where('active',true)->orderBy('name')->get(),'parts'=>SparePart::where('stock','>',0)->orderBy('nombre')->get(),'visits'=>\App\Models\TechnicalVisit::visibleTo($request->user())->where('solicitud_id',$ticket->id)->with('technician')->orderByDesc('inicio')->get()]); }
    public function act(Request $request, Ticket $ticket){ $this->authorizeView($request,$ticket); $ticket->load(['school','equipment','requester','technician','interventions.technician','interventions.spareParts']); return view('tickets.act',compact('ticket')); }
    public function assign(Request $request, Ticket $ticket){ abort_if($request->user()->isDirector(),403); $this->authorizeView($request,$ticket); $data=$request->validate(['assigned_to'=>'required|exists:users,id']); $ticket->update($data); return back()->with('success','Técnico asignado.'); }
    public function updateStatus(Request $request, Ticket $ticket){ abort_if($request->user()->isDirector(),403); $this->authorizeView($request,$ticket); $data=$request->validate(['status'=>'required|in:pending,diagnosis,waiting_parts,in_progress,resolved,closed,cancelled','comment'=>'nullable|string|max:1000']); $from=$ticket->status; DB::transaction(function()use($ticket,$data,$from,$request){$ticket->update(['status'=>$data['status'],'resolved_at'=>$data['status']==='resolved'?now():$ticket->resolved_at]); TicketStatusHistory::create(['ticket_id'=>$ticket->id,'changed_by'=>$request->user()->id,'from_status'=>$from,'to_status'=>$data['status'],'comment'=>$data['comment']??null]); if(in_array($data['status'],['resolved','closed']))$ticket->equipment?->update(['status'=>'operational']);}); $ticket->requester->notify(new TicketEventNotification($ticket,'status')); return back()->with('success','Estado actualizado.'); }
    private function scope($q,Request $r){ if($r->user()->isDirector())$q->where('unidad_educativa_id',$r->user()->school_id); elseif($r->user()->isTechnician())$q->where(fn($x)=>$x->where('tecnico_asignado_id',$r->user()->id)->orWhereNull('tecnico_asignado_id')); }
    private function authorizeView(Request $r,Ticket $t){ if($r->user()->isDirector())abort_unless($t->school_id===$r->user()->school_id,403); if($r->user()->isTechnician())abort_unless($t->assigned_to===$r->user()->id||is_null($t->assigned_to),403); }
}
